// Gym Tracker App
(function() {
    'use strict';

    // State
    let workouts = JSON.parse(localStorage.getItem('gymWorkouts')) || [];

    // DOM Elements
    const tabBtns = document.querySelectorAll('.tab-btn');
    const tabContents = document.querySelectorAll('.tab-content');
    const workoutForm = document.getElementById('workout-form');
    const setsContainer = document.getElementById('sets-container');
    const addSetBtn = document.getElementById('add-set-btn');
    const workoutDate = document.getElementById('workout-date');
    const todaySummary = document.getElementById('today-summary');
    const todayExercises = document.getElementById('today-exercises');
    const historyList = document.getElementById('history-list');
    const searchHistory = document.getElementById('search-history');
    const filterMuscle = document.getElementById('filter-muscle');
    const clearDataBtn = document.getElementById('clear-data-btn');
    const exerciseSuggestions = document.getElementById('exercise-suggestions');
    const toast = document.getElementById('toast');

    // Initialize
    function init() {
        workoutDate.value = getTodayString();
        setupTabs();
        setupForm();
        setupHistory();
        setupStats();
        updateTodaySummary();
        updateExerciseSuggestions();
    }

    // Utility functions
    function getTodayString() {
        const d = new Date();
        return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
    }

    function formatDate(dateStr) {
        const d = new Date(dateStr + 'T00:00:00');
        const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
        return d.toLocaleDateString('en-US', options);
    }

    function saveWorkouts() {
        localStorage.setItem('gymWorkouts', JSON.stringify(workouts));
    }

    function showToast(message) {
        toast.textContent = message;
        toast.classList.remove('hidden');
        toast.classList.add('show');
        setTimeout(() => {
            toast.classList.remove('show');
            setTimeout(() => toast.classList.add('hidden'), 400);
        }, 2500);
    }

    function generateId() {
        return Date.now().toString(36) + Math.random().toString(36).substr(2);
    }

    // Tabs
    function setupTabs() {
        tabBtns.forEach(btn => {
            btn.addEventListener('click', () => {
                const tab = btn.dataset.tab;
                tabBtns.forEach(b => b.classList.remove('active'));
                tabContents.forEach(c => c.classList.remove('active'));
                btn.classList.add('active');
                document.getElementById(tab).classList.add('active');

                if (tab === 'history') renderHistory();
                if (tab === 'stats') renderStats();
            });
        });
    }

    // Form & Sets
    function setupForm() {
        addSetBtn.addEventListener('click', addSetRow);
        setsContainer.addEventListener('click', (e) => {
            if (e.target.classList.contains('remove-set-btn')) {
                const rows = setsContainer.querySelectorAll('.set-row');
                if (rows.length > 1) {
                    e.target.closest('.set-row').remove();
                    renumberSets();
                }
            }
        });

        workoutForm.addEventListener('submit', (e) => {
            e.preventDefault();
            logExercise();
        });
    }

    function addSetRow() {
        const rows = setsContainer.querySelectorAll('.set-row');
        const num = rows.length + 1;
        const row = document.createElement('div');
        row.className = 'set-row';
        row.innerHTML = `
            <span class="set-number">Set ${num}</span>
            <div class="set-inputs">
                <div class="input-pair">
                    <label>Weight (lbs)</label>
                    <input type="number" class="set-weight" placeholder="0" min="0" step="0.5">
                </div>
                <div class="input-pair">
                    <label>Reps</label>
                    <input type="number" class="set-reps" placeholder="0" min="0" required>
                </div>
            </div>
            <button type="button" class="remove-set-btn" title="Remove set">✕</button>
        `;
        setsContainer.appendChild(row);
    }

    function renumberSets() {
        const rows = setsContainer.querySelectorAll('.set-row');
        rows.forEach((row, i) => {
            row.querySelector('.set-number').textContent = 'Set ' + (i + 1);
        });
    }

    function logExercise() {
        const name = document.getElementById('exercise-name').value.trim();
        const muscle = document.getElementById('muscle-group').value;
        const notes = document.getElementById('workout-notes').value.trim();
        const date = workoutDate.value;

        if (!name || !muscle || !date) {
            showToast('Please fill in all required fields');
            return;
        }

        const setRows = setsContainer.querySelectorAll('.set-row');
        const sets = [];
        let valid = true;

        setRows.forEach(row => {
            const weight = parseFloat(row.querySelector('.set-weight').value) || 0;
            const reps = parseInt(row.querySelector('.set-reps').value) || 0;
            if (reps === 0) valid = false;
            sets.push({ weight, reps });
        });

        if (!valid) {
            showToast('Each set needs at least 1 rep');
            return;
        }

        const exercise = {
            id: generateId(),
            name,
            muscleGroup: muscle,
            sets,
            notes,
            date
        };

        workouts.push(exercise);
        saveWorkouts();

        // Reset form
        document.getElementById('exercise-name').value = '';
        document.getElementById('muscle-group').value = '';
        document.getElementById('workout-notes').value = '';

        // Reset sets to one empty set
        setsContainer.querySelectorAll('.set-row').forEach((row, i) => {
            if (i > 0) row.remove();
            else {
                row.querySelector('.set-weight').value = '';
                row.querySelector('.set-reps').value = '';
            }
        });

        updateTodaySummary();
        updateExerciseSuggestions();
        showToast('Exercise logged! 💪');
    }

    function updateTodaySummary() {
        const today = workoutDate.value || getTodayString();
        const todayWorkouts = workouts.filter(w => w.date === today);

        if (todayWorkouts.length === 0) {
            todaySummary.classList.add('hidden');
            return;
        }

        todaySummary.classList.remove('hidden');
        todayExercises.innerHTML = todayWorkouts.map(w => {
            const setsSummary = w.sets.map((s, i) => `${s.weight}lb × ${s.reps}`).join(', ');
            return `
                <div class="today-exercise-item">
                    <div class="exercise-info">
                        <h4>${w.name}</h4>
                        <p>${w.muscleGroup} — ${setsSummary}</p>
                    </div>
                    <button class="delete-exercise-btn" data-id="${w.id}" title="Delete">🗑️</button>
                </div>
            `;
        }).join('');

        // Bind delete buttons
        todayExercises.querySelectorAll('.delete-exercise-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                const id = btn.dataset.id;
                workouts = workouts.filter(w => w.id !== id);
                saveWorkouts();
                updateTodaySummary();
                showToast('Exercise removed');
            });
        });
    }

    function updateExerciseSuggestions() {
        const names = [...new Set(workouts.map(w => w.name))];
        exerciseSuggestions.innerHTML = names.map(n => `<option value="${n}">`).join('');
    }

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    --primary: #6c5ce7;
    --primary-dark: #5a4bd1;
    --secondary: #00cec9;
    --accent: #fd79a8;
    --bg: #0a0a1a;
    --bg-card: #141432;
    --bg-input: #1a1a3e;
    --text: #f0f0f5;
    --text-muted: #8888aa;
    --border: #2a2a5a;
    --success: #00b894;
    --danger: #e17055;
    --warning: #fdcb6e;
    --radius: 12px;
    --shadow: 0 4px 20px rgba(0, 0, 0, 0.3);
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, sans-serif;
    background: var(--bg);
    color: var(--text);
    min-height: 100vh;
    line-height: 1.6;
}

.app-container {
    max-width: 600px;
    margin: 0 auto;
    padding: 20px;
    padding-bottom: 40px;
}

header {
    text-align: center;
    padding: 30px 0 20px;
}

header h1 {
    font-size: 2rem;
    background: linear-gradient(135deg, var(--primary), var(--secondary));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.subtitle {
    color: var(--text-muted);
    font-size: 0.9rem;
    margin-top: 4px;
}

/* Tabs */
.tabs {
    display: flex;
    gap: 4px;
    background: var(--bg-card);
    padding: 4px;
    border-radius: var(--radius);
    margin-bottom: 24px;
}

.tab-btn {
    flex: 1;
    padding: 12px 16px;
    border: none;
    background: transparent;
    color: var(--text-muted);
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    border-radius: 10px;
    transition: all 0.3s ease;
}

.tab-btn.active {
    background: var(--primary);
    color: white;
    box-shadow: 0 2px 10px rgba(108, 92, 231, 0.4);
}

.tab-btn:hover:not(.active) {
    color: var(--text);
    background: var(--bg-input);
}

/* Tab Content */
.tab-content {
    display: none;
    animation: fadeIn 0.3s ease;
}

.tab-content.active {
    display: block;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Form */
.form-group {
    margin-bottom: 16px;
}

.form-group label {
    display: block;
    margin-bottom: 6px;
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

input[type="text"],
input[type="number"],
input[type="date"],
select,
textarea {
    width: 100%;
    padding: 12px 16px;
    background: var(--bg-input);
    border: 2px solid var(--border);
    border-radius: var(--radius);
    color: var(--text);
    font-size: 1rem;
    transition: border-color 0.3s ease;
    outline: none;
}

input:focus,
select:focus,
textarea:focus {
    border-color: var(--primary);
}

textarea {
    resize: vertical;
    min-height: 80px;
}

/* Sets */
#sets-container {
    margin-bottom: 12px;
}

#sets-container h3 {
    font-size: 0.85rem;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 10px;
}

.set-row {
    display: flex;
    align-items: center;
    gap: 10px;
    background: var(--bg-input);
    padding: 12px;
    border-radius: var(--radius);
    margin-bottom: 8px;
    border: 1px solid var(--border);
}

.set-number {
    font-weight: 700;
    color: var(--primary);
    min-width: 45px;
    font-size: 0.85rem;
}

.set-inputs {
    display: flex;
    gap: 10px;
    flex: 1;
}

.input-pair {
    flex: 1;
}

.input-pair label {
    font-size: 0.7rem;
    color: var(--text-muted);
    margin-bottom: 4px;
    display: block;
}

.input-pair input {
    padding: 8px 10px;
    font-size: 0.9rem;
}

.remove-set-btn {
    background: none;
    border: none;
    color: var(--danger);
    cursor: pointer;
    font-size: 1rem;
    padding: 4px 8px;
    border-radius: 6px;
    transition: background 0.2s;
}

.remove-set-btn:hover {
    background: rgba(225, 112, 85, 0.2);
}

/* Buttons */
.primary-btn {
    width: 100%;
    padding: 14px 24px;
    background: linear-gradient(135deg, var(--primary), var(--primary-dark));
    color: white;
    border: none;
    border-radius: var(--radius);
    font-size: 1.05rem;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.3s ease;
    box-shadow: 0 4px 15px rgba(108, 92, 231, 0.3);
    margin-top: 8px;
}

.primary-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 25px rgba(108, 92, 231, 0.5);
}

.secondary-btn {
    width: 100%;
    padding: 10px 16px;
    background: transparent;
    color: var(--secondary);
    border: 2px dashed var(--border);
    border-radius: var(--radius);
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    margin-bottom: 16px;
}

.secondary-btn:hover {
    border-color: var(--secondary);
    background: rgba(0, 206, 201, 0.1);
}

.danger-btn {
    width: 100%;
    padding: 12px 24px;
    background: transparent;
    color: var(--danger);
    border: 2px solid var(--danger);
    border-radius: var(--radius);
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    margin-top: 24px;
}

.danger-btn:hover {
    background: var(--danger);
    color: white;
}

/* Today Summary */
.today-summary {
    margin-top: 24px;
    padding: 20px;
    background: var(--bg-card);
    border-radius: var(--radius);
    border: 1px solid var(--border);
}

.today-summary h3 {
    margin-bottom: 12px;
    color: var(--secondary);
}

.today-exercise-item {
    padding: 12px;
    background: var(--bg-input);
    border-radius: 8px;
    margin-bottom: 8px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.today-exercise-item .exercise-info h4 {
    font-size: 0.95rem;
}

.today-exercise-item .exercise-info p {
    font-size: 0.8rem;
    color: var(--text-muted);
}

.today-exercise-item .delete-exercise-btn {
    background: none;
    border: none;
    color: var(--danger);
    cursor: pointer;
    font-size: 1.1rem;
    padding: 4px 8px;
    border-radius: 6px;
    transition: background 0.2s;
}

.today-exercise-item .delete-exercise-btn:hover {
    background: rgba(225, 112, 85, 0.2);
}

/* History */
.history-controls {
    display: flex;
    gap: 10px;
    margin-bottom: 20px;
}

.history-controls input {
    flex: 1;
}

.history-controls select {
    width: 180px;
}

.history-day {
    margin-bottom: 20px;
}

.history-date {
    font-size: 0.85rem;
    font-weight: 700;
    color: var(--secondary);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 10px;
    padding-bottom: 6px;
    border-bottom: 1px solid var(--border);
}

.history-exercise {
    background: var(--bg-card);
    padding: 14px;
    border-radius: var(--radius);
    margin-bottom: 8px;
    border: 1px solid var(--border);
}

.history-exercise-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 8px;
}

.history-exercise-header h4 {
    font-size: 1rem;
}

.muscle-tag {
    font-size: 0.7rem;
    padding: 3px 10px;
    background: rgba(108, 92, 231, 0.2);
    color: var(--primary);
    border-radius: 20px;
    font-weight: 600;
}

.history-sets {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.history-set {
    font-size: 0.8rem;
    padding: 4px 10px;
    background: var(--bg-input);
    border-radius: 6px;
    color: var(--text-muted);
}

.history-notes {
    margin-top: 8px;
    font-size: 0.8rem;
    color: var(--text-muted);
    font-style: italic;
}

.no-data {
    text-align: center;
    padding: 40px 20px;
    color: var(--text-muted);
}

.no-data .no-data-icon {
    font-size: 3rem;
    margin-bottom: 10px;
}

/* Stats */
.stats-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
    margin-bottom: 24px;
}

.stat-card {
    background: var(--bg-card);
    padding: 20px;
    border-radius: var(--radius);
    text-align: center;
    border: 1px solid var(--border);
    transition: transform 0.2s;
}

.stat-card:hover {
    transform: translateY(-2px);
}

.stat-icon {
    font-size: 1.5rem;
    margin-bottom: 6px;
}

.stat-value {
    font-size: 1.8rem;
    font-weight: 800;
    background: linear-gradient(135deg, var(--primary), var(--secondary));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.stat-label {
    font-size: 0.75rem;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-top: 2px;
}

.stats-section {
    margin-bottom: 24px;
}

.stats-section h3 {
    margin-bottom: 14px;
    font-size: 1rem;
    color: var(--text);
}

/* Muscle Chart */
.muscle-bar-container {
    margin-bottom: 10px;
}

.muscle-bar-label {
    display: flex;
    justify-content: space-between;
    font-size: 0.85rem;
    margin-bottom: 4px;
}

.muscle-bar-label span:last-child {
    color: var(--text-muted);
}

.muscle-bar {
    height: 8px;
    background: var(--bg-input);
    border-radius: 4px;
    overflow: hidden;
}

.muscle-bar-fill {
    height: 100%;
    border-radius: 4px;
    transition: width 0.5s ease;
}

/* PR Cards */
.pr-card {
    background: var(--bg-card);
    padding: 14px;
    border-radius: var(--radius);
    margin-bottom: 8px;
    border: 1px solid var(--border);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.pr-card .pr-exercise {
    font-weight: 600;
    font-size: 0.95rem;
}

.pr-card .pr-value {
    font-weight: 800;
    color: var(--warning);
    font-size: 1.1rem;
}

/* Weekly Chart */
.weekly-chart {
    display: flex;
    align-items: flex-end;
    gap: 8px;
    height: 120px;
    padding: 10px 0;
}

.weekly-bar {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    height: 100%;
    justify-content: flex-end;
}

.weekly-bar-fill {
    width: 100%;
    background: linear-gradient(180deg, var(--primary), var(--secondary));
    border-radius: 6px 6px 0 0;
    min-height: 2px;
    transition: height 0.5s ease;
}

.weekly-bar-label {
    font-size: 0.7rem;
    color: var(--text-muted);
    margin-top: 6px;
    font-weight: 600;
}

.weekly-bar-count {
    font-size: 0.7rem;
    color: var(--text);
    margin-bottom: 4px;
    font-weight: 700;
}

/* Toast */
.toast {
    position: fixed;
    bottom: 30px;
    left: 50%;
    transform: translateX(-50%) translateY(100px);
    background: var(--success);
    color: white;
    padding: 14px 28px;
    border-radius: var(--radius);
    font-weight: 600;
    font-size: 0.9rem;
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.4);
    transition: transform 0.4s ease;
    z-index: 1000;
}

.toast.show {
    transform: translateX(-50%) translateY(0);
}

.hidden {
    display: none !important;
}

/* Responsive */
@media (max-width: 480px) {
    .app-container {
        padding: 12px;
    }

    header h1 {
        font-size: 1.6rem;
    }

    .history-controls {
        flex-direction: column;
    }

    .history-controls select {
        width: 100%;
    }

    .stats-grid {
        grid-template-columns: 1fr 1fr;
        gap: 8px;
    }

    .stat-card {
        padding: 14px;
    }

    .stat-value {
        font-size: 1.4rem;
    }
}
